INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('b1e5eda0-df02-4f13-97b7-5372e1502dc9','bbbbbbbb-0001-0000-0000-000000000001',4,'*(UNISL Porto Velho)* A hemoglobina (Hb) é uma proteína encontrada exclusivamente nos eritrócitos cuja principal função é o transporte de O₂. Existem variações nas cadeias polipeptídicas que permitem classificá-las como **HbF**, **HbA1**, **HbA2** e **HbS** (associada à anemia falciforme).','Com base nessas informações, analise a figura das estruturas de hemoglobina e marque a alternativa que representa adequadamente cada tipo.','multipla_escolha','- **Figura A (α₂β₂)** = HbA1 — hemoglobina mais comum em adultos. - **Figura B (α₂γ₂)** = HbF — hemoglobina fetal, presente no feto e recém-nascido; alta afinidade por O₂ devido à baixa afinidade da cadeia γ pelo 2,3-BPG, garantindo transferência eficiente de O₂ da mãe para o feto. - **Figura C (α₂δ₂)** = HbA2 — representa 2–5% da Hb do adulto. **Alternativa correta: A.**','HARVEY, R. A.; FERRIER, D. R. Bioquímica Ilustrada de Ferrier. 5ª ed. Porto Alegre: Artmed, 2012.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('84db67c5-5d9e-4e70-95d2-593c3b73402b','b1e5eda0-df02-4f13-97b7-5372e1502dc9','A','A figura "B" representa a hemoglobina mais encontrada no feto e no recém-nascido.',true,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('3ee41a11-3604-4197-8b8b-c07005f95199','b1e5eda0-df02-4f13-97b7-5372e1502dc9','B','A figura "A" representa a hemoglobina que está em menor quantidade nos adultos.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('d3e9ff01-2668-48c9-ae3a-87e03727e652','b1e5eda0-df02-4f13-97b7-5372e1502dc9','C','A figura "B" representa a hemoglobina que possui menor afinidade com oxigênio.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('d75d20ed-6216-40f7-975f-02723b7e7909','b1e5eda0-df02-4f13-97b7-5372e1502dc9','D','A figura "C" representa a hemoglobina que está em maior quantidade nos adultos.',false,4);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('ecd8bd17-7558-4991-a127-d3e5e5c1c1e1','bbbbbbbb-0001-0000-0000-000000000001',5,'*(FACIMPA)* Homem, 55 anos, sedentário, tabagista, IMC 29 kg/m², sem queixas. PA consistentemente **150/95 mmHg** em três aferições. Exames laboratoriais não sugerem causa secundária. Diagnóstico: **Hipertensão Arterial Sistêmica (HAS) primária**.','Qual segmento da árvore vascular é o principal responsável pelo aumento da resistência vascular periférica total que fundamenta esse diagnóstico?','multipla_escolha','As **arteríolas** são os "vasos de resistência". Possuem túnica média espessa com músculo liso, inervação simpática densa e respondem a agentes vasoativos. A resistência é inversamente proporcional à **4ª potência do raio** (R∝1/r⁴): pequenas mudanças no diâmetro arteriolar causam grandes variações na resistência vascular periférica. Por isso são o principal local de controle da RVP e da pressão arterial. **Alternativa correta: D.**','HALL, J. E. Guyton and Hall Textbook of Medical Physiology. 14th ed. Philadelphia: Elsevier, 2021. Cap. 17.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('e9b47e4f-5dcf-4454-aa17-b03732196aa3','ecd8bd17-7558-4991-a127-d3e5e5c1c1e1','A','As grandes artérias elásticas, como a aorta, que perdem complacência com a idade.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('64cafefa-fd95-42d4-9615-c4fe60ce8d0f','ecd8bd17-7558-4991-a127-d3e5e5c1c1e1','C','Os capilares, pois representam a maior área de secção transversal total do sistema.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('89f1508a-ab8c-4283-b666-3dcc22b4fa92','ecd8bd17-7558-4991-a127-d3e5e5c1c1e1','D','As arteríolas, devido à sua capacidade de contrair a espessa camada de músculo liso, regulando ativamente o fluxo sanguíneo.',true,3);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('a8f9b50f-d779-4954-a6da-2582a71a9ccb','bbbbbbbb-0001-0000-0000-000000000001',6,'*(AFYA Manacapuru)* Paciente com anemia ferropriva crônica: dispneia, palidez, fadiga, VCM baixo. Alunos analisam hemograma completo e lâminas de medula óssea hematopoiética.','Avalie as asserções sobre eritropoiese e a relação entre elas: **I.** A eritropoiese é regulada pela eritropoietina (EPO), secretada pelos rins em resposta à hipóxia, e depende de ferro, vitamina B12 e ácido fólico para síntese de hemoglobina e maturação das hemácias. **PORQUE** **II.** A EPO estimula apenas os estágios finais da diferenciação eritroide, sem influenciar células progenitoras nem depender de substratos nutricionais.','multipla_escolha','**Asserção I — Verdadeira.** EPO aumenta em hipóxia; a eritropoiese depende de ferro (síntese de heme), B12 e folato (síntese de DNA para divisão celular). **Asserção II — Falsa.** A EPO age desde progenitores comprometidos (UFC-E) até fases intermediárias, e sua ação depende de substratos adequados. **Alternativa correta: A.**','HALL, J. E.; HALL, M. E. Guyton & Hall Fundamentos de Fisiologia. 14. ed. Rio de Janeiro: GEN Guanabara Koogan, 2023.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('4b39d5d8-99e8-4409-b26c-fe72cedda0a3','a8f9b50f-d779-4954-a6da-2582a71a9ccb','A','A asserção I é verdadeira e a II é falsa.',true,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('3edaec14-0b13-4a39-9e5f-f09eb983aa6b','a8f9b50f-d779-4954-a6da-2582a71a9ccb','B','A asserção I é falsa e a II é verdadeira.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('657243d8-8476-4980-b545-1ab777f0dfc3','a8f9b50f-d779-4954-a6da-2582a71a9ccb','C','As asserções I e II são verdadeiras, mas a II não é justificativa correta da I.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('d4222eed-39e7-41b7-8a06-45dd9563a638','a8f9b50f-d779-4954-a6da-2582a71a9ccb','D','As asserções I e II são verdadeiras e a II é justificativa correta da I.',false,4);;
